('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000000701','authenticated','authenticated','admin-p7@example.invalid','',now(),'{}','{}',now(),now(),'','','',''),
('00000000-0000-0000-0000-000000000000','00000000-0000-4000-8000-000000000702','authenticated','authenticated','user-p7@example.invalid','',now(),'{}','{}',now(),now(),'','','','');
insert into public.platform_admins(user_id)values('00000000-0000-4000-8000-000000000701');
insert into public.tenants(id,shop_name,business_type,branch_count,plan,status,setup_complete)values('00000000-0000-4000-8000-000000000703','Patch 7 Shop','retail',1,'starter','active',true);
insert into public.offline_mutation_failures(id,tenant_id,user_id,mutation_type,diagnostic_code)values('00000000-0000-4000-8000-000000000704','00000000-0000-4000-8000-000000000703','00000000-0000-4000-8000-000000000702','update_schedule','NETWORK_TIMEOUT');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000701',true);
do $test$ declare note_id uuid;begin note_id:=public.platform_add_support_note('00000000-0000-4000-8000-000000000703','00000000-0000-4000-8000-000000000702','account_recovery','Identity checked through approved support process');perform public.platform_resolve_support_note(note_id);perform public.platform_update_offline_failure('00000000-0000-4000-8000-000000000704','retry','Admin retry');if not exists(select 1 from public.platform_list_audit_logs('00000000-0000-4000-8000-000000000703','support.',null,null,null,200))then raise exception 'Filtered audit list empty';end if;if(select count(*)from public.platform_tenant_activity('00000000-0000-4000-8000-000000000703',100))<>3 then raise exception 'Tenant timeline incomplete';end if;end $test$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000702',true);do $test$begin begin perform public.platform_list_audit_logs();raise exception 'Non-admin audit access succeeded';exception when insufficient_privilege then if sqlstate<>'42501'then raise;end if;end;begin perform public.platform_list_failed_offline_mutations();raise exception 'Non-admin diagnostic access succeeded';exception when insufficient_privilege then if sqlstate<>'42501'then raise;end if;end;end $test$;
